<template>
<el-dialog v-model="visible" :title="`${form.id?'编辑':'添加'}${kindNames[kind]}`" width="1120px" class="storage-dialog" :close-on-click-modal="false" :before-close="close" destroy-on-close>
 <OperationStatus :operation="operation"/><el-alert v-if="state.optionsError" type="error" :closable="false"><template #title>{{state.optionsError}} <el-button link @click="refreshOptions">重试</el-button></template></el-alert><el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <el-form label-position="top" :disabled="operation.busy.value||!!operation.pending.value" v-loading="state.optionsLoading"><h3>基础信息</h3><div class="storage-grid">
 <el-form-item label="单据编号"><el-input :model-value="form.number||'保存后自动生成'" readonly/></el-form-item><el-form-item label="所属工厂"><el-input :model-value="state.factories.find(f=>f.id===state.factoryId)?.name" readonly/></el-form-item>
 <el-form-item label="单据类型" required><el-select :model-value="form.type" aria-label="单据类型" @change="changeType"><el-option v-for="t in typesFor(kind)" :key="t" :label="typeNames[t]" :value="t"/></el-select></el-form-item>
 <el-form-item label="单据日期" required><el-date-picker v-model="form.date" type="date" value-format="YYYY-MM-DD"/></el-form-item>
 <el-form-item v-if="productionRelated" label="生产工单" required><el-select :model-value="form.orderId" aria-label="生产工单" filterable @change="changeOrder"><el-option v-for="o in state.productionOrders" :key="o.id" :label="o.number" :value="o.id"/></el-select></el-form-item>
 <el-form-item v-if="form.type==='RAW_OUT'" label="关联原工单（可选）"><el-select v-model="form.orderId" clearable filterable @change="value=>{if(value)form.customerId=state.productionOrders.find(o=>o.id===value)?.customerId}"><el-option v-for="o in state.productionOrders" :key="o.id" :label="o.number" :value="o.id"/></el-select></el-form-item><el-form-item v-if="productionRelated" label="加工批次" required><el-select :model-value="form.executionId" aria-label="加工批次" filterable @change="changeExecution"><el-option v-for="e in executions" :key="e.id" :label="`${e.number||e.batchNo||e.id} / ${e.productName||''} / ${e.processName||''}`" :value="e.id"/></el-select></el-form-item>
 <el-form-item v-if="['RAW_OUT','PRODUCT_OUT','SEMI_OUT'].includes(form.type)" label="提料客户" required><el-select v-model="form.customerId" :disabled="form.type==='RAW_OUT'&&!!form.orderId"><el-option v-for="c in state.customers" :key="c.id" :value="c.id" :label="c.companyName||c.name"/></el-select></el-form-item>
 <el-form-item label="指定复验人员" required :error="reviewerProblem"><el-select v-model="form.reviewerId" aria-label="指定复验人员" filterable @visible-change="v=>v&&refreshOptions()"><el-option v-if="form.reviewerId&&!reviewers.some(p=>String(p.id)===String(form.reviewerId))" :value="String(form.reviewerId)" :label="selectedReviewerName" disabled/><el-option v-for="p in reviewers" :key="p.id" :label="p.name||p.nickName" :value="p.id"/></el-select></el-form-item>
 <el-form-item label="仓库/库房" v-if="kind!=='REVERSE'" required><el-select :model-value="singleWarehouse?form.warehouseIds[0]||'':form.warehouseIds" :multiple="!singleWarehouse" aria-label="仓库/库房" @change="changeWarehouses"><el-option v-for="w in state.warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item>
 <el-form-item v-if="kind==='REVERSE'" label="原单据"><el-input :model-value="form.reverseDocumentNumber||form.reverseDocumentId" readonly/></el-form-item>
 <el-form-item label="原因 / 备注" :required="['ADJUST','RETURN_RIGHTS','REVERSE'].includes(kind)" class="wide"><el-input v-model="form.reason" type="textarea" maxlength="500"/></el-form-item>
 </div><template v-if="kind!=='REVERSE'"><h3>物料清单</h3><el-tabs v-model="activeWarehouse"><el-tab-pane v-for="id in form.warehouseIds" :key="id" :name="id" :label="warehouseName(id)"/></el-tabs>
 <div class="line-actions"><el-button type="primary" :disabled="!activeWarehouse||!!state.optionsError" @click="lineEditor?.open()">添加物料</el-button><el-button v-if="['OUT','IN','RET'].includes(kind)" :disabled="!activeWarehouse" @click="templateCsv">下载模板</el-button><el-button v-if="['OUT','IN','RET'].includes(kind)" :disabled="!activeWarehouse||!!state.optionsError" @click="fileInput?.click()">导入</el-button><input ref="fileInput" hidden type="file" accept=".csv,text/csv" @change="importCsv"/></div>
 <el-alert v-if="!['ADJUSTMENT','OWNERSHIP_RETURN','REVERSAL'].includes(form.type)&&activeLines.some((row:any)=>!['WEIGHT','PIECE'].includes(row.measurementMode))" title="明细计量方式缺失，请编辑明细重新加载并核对配置" type="warning" :closable="false"/><el-table :data="activeLines" border><AdjustmentColumns v-if="form.type==='ADJUSTMENT'" :lines="activeLines"/><template v-else><el-table-column label="物料 / 产品"><template #default="{row}">{{row.code||row.materialId||row.stockId}} {{row.name}}<span v-if="form.type==='PRODUCTION_OUT'&&!state.optionsLoading&&!state.optionsError&&!state.stocks.some(s=>s.id===String(row.stockId)&&['RAW','SEMI'].includes(s.category))" style="color:var(--el-color-danger)">（不可用于生产领料，请重新选择）</span></template></el-table-column><el-table-column prop="netWeight" label="净重（g）"/><el-table-column prop="quantity" label="件数"/><el-table-column v-if="form.type==='PRODUCT_IN'&&(activeLines.length?activeLines.some((row:any)=>row.measurementMode==='WEIGHT'):state.executions.find(e=>e.id===form.executionId)?.measurementMode==='WEIGHT')" prop="referenceQuantity" label="参考完工件数"/><el-table-column v-if="kind==='ADJUST'" prop="deltaWeight" label="净重增减（g）"/><el-table-column v-if="kind==='ADJUST'" prop="deltaQuantity" label="件数增减"/><el-table-column prop="remark" label="备注"/></template><el-table-column label="操作" width="140"><template #default="{row}"><el-button link @click="lineEditor?.open(row)">编辑</el-button><el-button link type="danger" @click="form.lines=form.lines.filter((r:any)=>r!==row)">移除</el-button></template></el-table-column></el-table></template></el-form>
 <template #footer><el-button :disabled="operation.busy.value||!!operation.pending.value" @click="close()">取消</el-button><el-button :disabled="operation.busy.value||!!operation.pending.value" @click="save(false)">保存草稿</el-button><el-button type="primary" :loading="operation.busy.value" :disabled="!!operation.pending.value||!!state.optionsError" @click="save(true)">提交复验</el-button></template>
 <LineEditor ref="lineEditor" :type="form.type" :warehouse-id="activeWarehouse" :execution-id="form.executionId" :debt="form.debt" @save="saveLine"/>
</el-dialog>
</template>
<script setup lang="ts">
import AdjustmentColumns from '../storage-live/AdjustmentColumns.vue'
import {optionalPurityValid,purityError} from '@/utils/business-decimal'
import {computed,ref,watch} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import request from '@/utils/request'
import {useStorage,useOperation,today,uid,message,type Row} from '../storage-live/client';import OperationStatus from '../storage-live/OperationStatus.vue';import {kindNames,typeNames,typesFor,clone,type Kind} from './model';import LineEditor from './LineEditor.vue';import {parseCsv,downloadCsv} from '../storage-preview/csv'
const emit=defineEmits<{saved:[]}>(),{state,user,context,loadOptions}=useStorage(),base='/metal/storage-orders',visible=ref(false),kind=ref<Kind>('OUT'),form=ref<any>({lines:[],warehouseIds:[]}),activeWarehouse=ref(''),error=ref(''),lineEditor=ref<InstanceType<typeof LineEditor>>(),fileInput=ref<HTMLInputElement>()
let initial='',epoch=0,submitAfter=false,action='save'
const operation=useOperation(base,context,async data=>{if(action==='save'){Object.assign(form.value,data);initial=JSON.stringify(form.value);if(submitAfter){setTimeout(()=>{if(visible.value)void submit()},0);return}}visible.value=false;window.dispatchEvent(new Event('storage-documents-changed'));emit('saved');ElMessage.success(action==='submit'?'已提交复验':'草稿已保存')})
const productionRelated=computed(()=>['PRODUCTION_OUT','PROCESS_RAW_IN','SEMI_IN','PRODUCT_IN','RAW_RETURN','RECOVERY_RETURN'].includes(form.value.type))
const singleWarehouse=computed(()=>['RAW_IN','CUSTOMER_IN','RAW_RETURN','RECOVERY_RETURN'].includes(form.value.type))
const executions=computed(()=>state.executions.filter(e=>String(e.orderId)===String(form.value.orderId)&&e.status!=='CLOSED'))
const reviewers=computed(()=>state.people.filter(p=>String(p.id)!==String(form.value.creatorId||user.id)&&(p.status==null||String(p.status)==='0')&&(kind.value==='OUT'?p.canReceive!==false:p.canAccept!==false)&&(form.value.type!=='PRODUCTION_OUT'||String(p.id)===String(state.executions.find(e=>e.id===form.value.executionId)?.processorId))))
const selectedReviewerName=computed(()=>state.people.find(p=>String(p.id)===String(form.value.reviewerId))?.name||form.value.reviewerName||`人员#${form.value.reviewerId}（资料不可用）`)
const reviewerProblem=computed(()=>{if(!form.value.reviewerId||state.optionsLoading||state.optionsError||reviewers.value.some(p=>String(p.id)===String(form.value.reviewerId)))return '';return String(form.value.reviewerId)===String(form.value.creatorId||user.id)?(form.value.type==='PRODUCTION_OUT'?'批次加工人员不能复验本人发起的出库单，请调整人员或由其他仓管发起':'指定人员不能复验本人发起的单据，请选择其他本厂人员'):form.value.type==='PRODUCTION_OUT'?'批次加工人员没有有效的领料复验权限，请先编辑批次调整人员':'指定复验人员已不可用，请重新选择'})
const activeLines=computed(()=>form.value.lines.filter((l:any)=>l.warehouseId===activeWarehouse.value))
const warehouseName=(id:string)=>state.warehouses.find(w=>w.id===id)?.name||id
async function refreshOptions(){const current=context(),session=epoch,execution=form.value.executionId,type=form.value.type;await loadOptions({type,executionId:execution||undefined});if(!visible.value||session!==epoch||current!==context()||execution!==form.value.executionId||type!==form.value.type)return;if(type==='PRODUCTION_OUT'){const e=state.executions.find(e=>e.id===execution);if(e){form.value.reviewerId=String(e.processorId);form.value.reviewerName=e.processorName||state.people.find(p=>String(p.id)===String(e.processorId))?.name||''}}}
async function open(next:Kind,row?:Row,preset:any={}){if(operation.busy.value||operation.pending.value)return;epoch++;kind.value=next;error.value='';operation.clear();form.value={id:'',factoryId:state.factoryId,kind:next,type:typesFor(next)[0],version:0,reviewRound:0,date:today(),orderId:'',executionId:'',reviewerId:'',warehouseIds:[],lines:[],reason:'',...clone(preset)};if(row){const current=context();try{const r:any=await request({url:base+'/'+row.id,params:{factoryId:state.factoryId}});if(current!==context())return;Object.assign(form.value,r.data)}catch(e){error.value=message(e);return}}if(!form.value.warehouseIds?.length)form.value.warehouseIds=[...new Set(form.value.lines.map((l:any)=>String(l.warehouseId)))];form.value.lines=form.value.lines.map((l:any)=>({...l,localId:l.localId||uid()}));activeWarehouse.value=form.value.warehouseIds[0]||'';initial=JSON.stringify(form.value);visible.value=true;await refreshOptions()}
async function allowClear(){if(!form.value.lines.length)return true;try{await ElMessageBox.confirm('变更选择将清空现有物料清单，是否继续？','确认变更');return true}catch{return false}}
async function changeType(value:string){if(value===form.value.type||!await allowClear())return;form.value.type=value;form.value.lines=[];if(singleWarehouse.value&&form.value.warehouseIds.length>1)form.value.warehouseIds=[];activeWarehouse.value=form.value.warehouseIds[0]||'';await refreshOptions()}
async function changeOrder(value:string){if(!await allowClear())return;form.value.orderId=value;form.value.executionId='';form.value.lines=[];await refreshOptions()}
async function changeExecution(value:string){if(!await allowClear())return;form.value.executionId=value;form.value.lines=[];await refreshOptions()}
async function changeWarehouses(value:string|string[]){const ids=(Array.isArray(value)?value:[value]).filter(Boolean);if(form.value.lines.some((l:any)=>!ids.includes(l.warehouseId))&&!await allowClear())return;form.value.lines=form.value.lines.filter((l:any)=>ids.includes(l.warehouseId));form.value.warehouseIds=ids;activeWarehouse.value=ids[0]||''}
function saveLine(line:any){const at=form.value.lines.findIndex((l:any)=>l.localId===line.localId);if(at<0)form.value.lines.push(line);else form.value.lines[at]=line}
async function save(send:boolean){if(operation.pending.value||operation.busy.value)return;error.value='';if(reviewerProblem.value){error.value=reviewerProblem.value;return;}if(form.value.type==='PRODUCTION_OUT'&&form.value.lines.some((l:any)=>!state.stocks.some(s=>s.id===String(l.stockId)&&['RAW','SEMI'].includes(s.category)))){error.value='生产领料仅支持本厂原料或半成品，请重新选择失效明细';return;}if(send&&['RAW_OUT','PRODUCT_OUT','SEMI_OUT'].includes(form.value.type)&&!form.value.customerId){error.value='请选择提料客户';return}if(send&&(!form.value.reviewerId||!form.value.date||productionRelated.value&&!form.value.executionId||kind.value!=='REVERSE'&&!form.value.lines.length)){error.value='请补齐复验人员、日期、加工批次和物料明细';return}submitAfter=send;action='save';const payload=clone(form.value);delete payload.debt;if(payload.type!=='EXTERNAL_SEMI_IN')for(const line of payload.lines)delete line.externalSource;await operation.send(base+(form.value.id?'/'+form.value.id:''),payload,form.value.id?'put':'post')}
async function submit(){action='submit';await operation.send(`${base}/${form.value.id}/submit`,{factoryId:state.factoryId,version:form.value.version,reviewRound:form.value.reviewRound})}
async function close(done?:()=>void){if(operation.busy.value||operation.pending.value)return;const current=context();if(visible.value&&JSON.stringify(form.value)!==initial){try{await ElMessageBox.confirm('放弃未保存的单据内容？','确认关闭',{confirmButtonText:'放弃',cancelButtonText:'继续填写'})}catch{return}}if(current!==context())return;visible.value=false;done?.()}
const csvFields=['stockId','materialId','productId','issueLineId','ownerId','netWeight','quantity','referenceQuantity','factoryWeight','purity','form','sourceReference','completedProcessIds','remark']
const csvLabels=['库存ID','物料ID','产品ID','原领料明细ID','料权客户ID(工厂填0)','净重(g)','数量(件)','参考完工件数','工厂料实测归还重量(g)','纯度(%)','形态(POWDER/UNTREATED/METAL)','外部来源凭证','已完成工序ID(分号分隔)','备注']
function templateCsv(){downloadCsv(typeNames[form.value.type]+'模板',csvLabels,[])}
async function importCsv(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;const current=context(),session=epoch;try{if(file.size>2*1024*1024)throw Error('CSV不能超过2MB');const rows=parseCsv(await file.text());if(rows.length>501)throw Error('一次最多500行');if(rows[0]?.join('|')!==csvLabels.join('|'))throw Error('请使用当前模板');const lines=rows.slice(1).map((r,index)=>{const fail=(m:string)=>{throw Error(`第${index+2}行：${m}`)};if(r.length!==csvFields.length)fail('字段数量错误');const l:any=Object.fromEntries(csvFields.map((f,i)=>[f,r[i].trim()]));const needsStock=kind.value==='OUT'||kind.value==='RET',stock=state.stocks.find(x=>x.id===l.stockId),material=state.materials.find(x=>x.id===l.materialId),product=state.products.find(x=>x.id===l.productId),execution=state.executions.find(x=>x.id===form.value.executionId);if(form.value.type==='PRODUCTION_OUT'&&stock?.category==='PRODUCT')fail('生产领料不能选择成品');if(needsStock&&!stock)fail(form.value.type==='PRODUCTION_OUT'?'生产领料仅支持本厂原料或半成品，不能选择成品':'库存不属于本厂');const category=({RAW_OUT:'RAW',PRODUCT_OUT:'PRODUCT',SEMI_OUT:'SEMI'} as Record<string,string>)[form.value.type];if(category&&stock?.category!==category)fail('库存类别与提料类型不符');if(kind.value==='OUT'&&stock?.warehouseId!==activeWarehouse.value)fail('库存不属于当前仓库');if(!needsStock&&!material&&!product)fail('请选择本厂物料或产品');if(l.ownerId&&l.ownerId!=='0'&&!state.customers.some(x=>x.id===l.ownerId))fail('料权客户不属于本厂');if(!/^\d{1,14}(\.\d{1,2})?$/.test(l.netWeight)||Number(l.netWeight)<=0)fail('净重须为正数且最多两位小数');const mode=stock?.measurementMode||execution?.measurementMode||material?.measurementMode;if(!mode)fail('未配置计量方式');if(mode==='PIECE'&&!/^[1-9]\d{0,8}$/.test(l.quantity))fail('请填写正整数件数');if(form.value.type==='PRODUCT_IN'&&mode==='WEIGHT'&&!/^[1-9]\d{0,8}$/.test(l.referenceQuantity))fail('请填写参考完工件数');if(!optionalPurityValid(l.purity))fail(purityError);if(kind.value==='RET'&&!l.issueLineId)fail('缺少原领料明细ID');if(form.value.type==='EXTERNAL_SEMI_IN'&&(!l.sourceReference||!l.completedProcessIds))fail('请填写外部来源与完整已完成工序');return {...l,...(form.value.type==='EXTERNAL_SEMI_IN'?{externalSource:{sourceReference:l.sourceReference,completedProcessIds:l.completedProcessIds.split(';').filter(Boolean)}}:{}),localId:uid(),warehouseId:activeWarehouse.value,measurementMode:mode,quantity:mode==='PIECE'?l.quantity:null,ownerId:l.ownerId||'0',form:l.form||material?.materialForm,allocations:[],debtAllocations:[],code:stock?.identity?.code||material?.code,name:stock?.identity?.name||material?.name||product?.name}});if(current===context()&&session===epoch)form.value.lines.push(...lines)}catch(e){error.value=message(e)}}

watch(()=>[state.factoryId,user.sessionEpoch],()=>{epoch++;visible.value=false})
defineExpose({open,requestClose:async()=>{await close();return !visible.value}})
</script>
<style scoped>.line-actions{display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap}.storage-grid .el-select{width:100%}</style>
